import{_ as r,o as a,c as o,a2 as e}from"./chunks/framework.CRFziyHp.js";const c=JSON.parse('{"title":"优惠券与推广","description":"","frontmatter":{},"headers":[],"relativePath":"features/coupon.md","filePath":"features/coupon.md","lastUpdated":1785013113000}'),l={name:"features/coupon.md"};function n(s,t,i,d,h,g){return a(),o("div",null,[...t[0]||(t[0]=[e('<h1 id="优惠券与推广" tabindex="-1">优惠券与推广 <a class="header-anchor" href="#优惠券与推广" aria-label="Permalink to &quot;优惠券与推广&quot;">​</a></h1><h2 id="功能说明" tabindex="-1">功能说明 <a class="header-anchor" href="#功能说明" aria-label="Permalink to &quot;功能说明&quot;">​</a></h2><p>配置区域推广员规则、营销优惠券活动，并查看发放与核销数据。</p><h2 id="前置条件" tabindex="-1">前置条件 <a class="header-anchor" href="#前置条件" aria-label="Permalink to &quot;前置条件&quot;">​</a></h2><ul><li>推广、优惠券相关模块已在授权中开通。</li><li>若优惠券需用户付费领取，须先配置 <a href="/features/payment">支付与提现</a>。</li><li>已创建目标 <strong>区域</strong>。</li></ul><h2 id="管理后台配置步骤" tabindex="-1">管理后台配置步骤 <a class="header-anchor" href="#管理后台配置步骤" aria-label="Permalink to &quot;管理后台配置步骤&quot;">​</a></h2><h3 id="推广员" tabindex="-1">推广员 <a class="header-anchor" href="#推广员" aria-label="Permalink to &quot;推广员&quot;">​</a></h3><p>路径：<strong>平台推广 → 推广员</strong> 分组</p><table tabindex="0"><thead><tr><th>菜单</th><th>作用</th></tr></thead><tbody><tr><td><strong>推广员审核</strong></td><td>审核用户推广员申请</td></tr><tr><td><strong>邀请记录</strong></td><td>查看邀请关系与奖励</td></tr><tr><td><strong>推广配置</strong></td><td>按区域设置推广奖励、层级、结算规则</td></tr></tbody></table><h3 id="平台营销券中心" tabindex="-1">平台营销券中心 <a class="header-anchor" href="#平台营销券中心" aria-label="Permalink to &quot;平台营销券中心&quot;">​</a></h3><p>路径：<strong>平台推广 → 平台营销券中心</strong> 分组</p><p>建议按以下顺序操作：</p><ol><li><strong>券模板</strong> — 定义券面额、门槛、有效期</li><li><strong>区域配置</strong> — 各区域是否启用营销券、补贴上限</li><li><strong>营销活动 / 营销配置</strong> — 创建发放活动、领取规则</li><li><strong>券包商品</strong>（如有）— 可购买的券包</li><li><strong>发放营销券</strong> — 手动向用户发放</li><li><strong>营销券列表 / 核销记录</strong> — 查询用户持有与使用</li><li><strong>运营看板 / 归因漏斗</strong> — 数据统计</li><li><strong>补贴审批 / A/B 实验</strong> — 高级运营（按需）</li></ol><h2 id="区域配置" tabindex="-1">区域配置 <a class="header-anchor" href="#区域配置" aria-label="Permalink to &quot;区域配置&quot;">​</a></h2><table tabindex="0"><thead><tr><th>菜单</th><th>说明</th></tr></thead><tbody><tr><td><strong>平台推广 → 推广员 → 推广配置</strong></td><td>推广员佣金、邀请规则按区域</td></tr><tr><td><strong>平台推广 → 平台营销券中心 → 区域配置</strong></td><td>营销券在该区域的开关与预算</td></tr></tbody></table><p>未单独配置的区域可继承平台默认策略（以各页面「平台默认」行为为准）。</p><h2 id="验证是否生效" tabindex="-1">验证是否生效 <a class="header-anchor" href="#验证是否生效" aria-label="Permalink to &quot;验证是否生效&quot;">​</a></h2><ol><li>在 <strong>推广配置</strong> 中开启测试区域并设置简单奖励规则。</li><li>测试用户申请推广员，在 <strong>推广员审核</strong> 中通过；生成邀请链接后新用户注册，<strong>邀请记录</strong> 可见。</li><li>创建券模板与活动，客户端可领取；下单核销后 <strong>核销记录</strong> 有数据。</li></ol><h2 id="常见问题" tabindex="-1">常见问题 <a class="header-anchor" href="#常见问题" aria-label="Permalink to &quot;常见问题&quot;">​</a></h2><p><strong>侧栏没有平台推广</strong></p><ul><li>模块未在授权中开通；或当前账号无推广 / 优惠券权限。</li></ul><p><strong>用户领券失败</strong></p><ul><li><strong>区域配置</strong> 是否关闭该区域营销券。</li><li>活动是否在有效期内；库存或补贴额度是否用尽。</li></ul><p><strong>推广奖励未到账</strong></p><ul><li><strong>推广配置</strong> 中结算周期、最低提现门槛。</li><li>在 <strong>财务管理 → 余额流水</strong> 查用户是否入账。</li></ul><p><strong>与抽奖、外卖券的区别</strong></p><ul><li>本模块为 <strong>平台营销券</strong>；外卖商家自有优惠在 <strong>商户管理 → 外卖</strong> 下配置。</li></ul><h2 id="相关文档" tabindex="-1">相关文档 <a class="header-anchor" href="#相关文档" aria-label="Permalink to &quot;相关文档&quot;">​</a></h2><ul><li><a href="/features/lottery">抽奖活动</a></li><li><a href="/features/payment">支付与提现</a></li><li><a href="/config/region">区域管理</a></li></ul>',29)])])}const p=r(l,[["render",n]]);export{c as __pageData,p as default};
